INSERT INTO categories (id, name, description, is_active) VALUES
(1, 'Networking & Connectivity', 'Corporate VPN, firewall rules, DNS resolution, Wi-Fi and WAN links', true),
(2, 'Identity & Access Management', 'Active Directory, SSO, MFA tokens, RBAC permissions and account lockouts', true),
(3, 'Database & Storage', 'PostgreSQL clusters, connection pools, slow queries, SAN backups and disk I/O', true),
(4, 'Cloud Infrastructure & DevOps', 'Kubernetes pods, Docker registries, CI/CD pipelines and ingress controllers', true),
(5, 'Enterprise Applications & ERP', 'SAP, CRM integrations, billing microservices and internal web portals', true),
(6, 'Endpoint & Hardware', 'Corporate laptops, docking stations, BitLocker encryption and OS updates', true);
INSERT INTO knowledge_articles (id, title, content, reference_url, is_active, is_verified, category_id, author_user_id, created_at, updated_at) VALUES
(1, 'IPSec VPN Error 809 Troubleshooting Runbook', 'Verify UDP ports 500 and 4500 on perimeter firewall and restart IKEEXT and PolicyAgent services on Windows 11 clients.', 'https://kb.enterprise.io/net/vpn-error-809', true, true, 1, 2, '2026-09-05 10:00:00', '2026-09-05 10:00:00'),
(2, 'Corporate DNS Split-Horizon Resolution Guide', 'Flush local DNS cache and confirm internal forwarders 10.20.0.10 and 10.20.0.11 are reachable over the VPN interface.', 'https://kb.enterprise.io/net/dns-split-horizon', true, true, 1, 2, '2026-09-05 11:00:00', '2026-09-05 11:00:00'),
(3, 'Active Directory Account Lockout & Kerberos Ticket Reset', 'Inspect Event ID 4740 on domain controller, clear cached credentials in Credential Manager and run klist purge.', 'https://kb.enterprise.io/iam/ad-lockout-4740', true, true, 2, 3, '2026-09-06 09:30:00', '2026-09-06 09:30:00'),
(4, 'Okta SSO SAML Clock Skew and MFA Resynchronization', 'Ensure NTP synchronization on identity provider nodes and re-enroll TOTP hardware tokens when drift exceeds 120 seconds.', 'https://kb.enterprise.io/iam/sso-saml-skew', true, true, 2, 3, '2026-09-06 14:00:00', '2026-09-06 14:00:00'),
(5, 'PostgreSQL HikariCP Connection Pool Exhaustion Mitigation', 'Identify idle-in-transaction sessions via pg_stat_activity, tune maximumPoolSize and set leakDetectionThreshold=30000.', 'https://kb.enterprise.io/db/hikaricp-exhaustion', true, true, 3, 4, '2026-09-07 10:15:00', '2026-09-07 10:15:00'),
(6, 'PostgreSQL Autovacuum Tuning and Dead Tuple Cleanup', 'Lower autovacuum_vacuum_scale_factor to 0.05 on high-churn tables to prevent transaction ID wraparound and table bloat.', 'https://kb.enterprise.io/db/autovacuum-tuning', true, true, 3, 4, '2026-09-07 16:00:00', '2026-09-07 16:00:00'),
(7, 'Kubernetes Pod OOMKilled (Exit Code 137) Diagnosis', 'Analyze container memory working set in Prometheus and increase resources.limits.memory or JVM MaxRAMPercentage.', 'https://kb.enterprise.io/cloud/k8s-oomkilled-137', true, true, 4, 2, '2026-09-08 09:00:00', '2026-09-08 09:00:00'),
(8, 'NGINX Ingress 502 Bad Gateway and Upstream Timeout Fix', 'Increase proxy-read-timeout annotation and verify readinessProbe endpoint health on backend microservices.', 'https://kb.enterprise.io/cloud/nginx-ingress-502', true, true, 4, 3, '2026-09-08 11:30:00', '2026-09-08 11:30:00'),
(9, 'ERP Billing Webhook Deadlock and Retry Queue Recovery', 'Replay dead-letter queue messages in RabbitMQ after clearing stale row locks in the invoice_headers table.', 'https://kb.enterprise.io/erp/billing-dlq-recovery', true, true, 5, 4, '2026-09-09 10:00:00', '2026-09-09 10:00:00'),
(10, 'BitLocker Recovery Prompt After BIOS Firmware Update', 'Suspend BitLocker protection for one reboot cycle using Manage-bde -Protectors -Disable C: and reseal TPM 2.0 PCR7.', 'https://kb.enterprise.io/endpoint/bitlocker-tpm-pcr7', true, true, 6, 2, '2026-09-10 08:45:00', '2026-09-10 08:45:00');
