INSERT INTO ai_responses (id, ai_query_id, suggested_diagnosis, solution_steps, confidence_score, processing_time_ms, responded_at) VALUES
(1, 1, 'Firewall NAT-T UDP 4500 port block detected for Windows 11 IPSec client.', '1. Verify UDP 500/4500 rules on perimeter firewall. 2. Restart IKEEXT service on client.', 0.94, 1850, '2026-09-14 11:15:02'),
(2, 2, 'NTP clock drift exceeding 120 seconds between Okta IdP and CRM service provider.', '1. Sync chronyd NTP service on CRM server. 2. Re-test SAML assertion login.', 0.91, 2120, '2026-09-14 14:30:02'),
(3, 3, 'Unclosed database transactions holding row locks and exhausting HikariCP pool.', '1. Terminate idle_in_transaction PIDs in pg_stat_activity. 2. Set leakDetectionThreshold=30000.', 0.96, 1940, '2026-09-15 09:20:02'),
(4, 4, 'Container JVM heap exceeding Kubernetes pod memory limit during batch job.', '1. Increase pod memory limit to 2Gi. 2. Configure -XX:MaxRAMPercentage=75.0.', 0.89, 2410, '2026-09-15 12:10:03');
